const listDeploymentsForCompare = `-- name: ListDeploymentsForCompare :many
SELECT deployment_id,
       MIN(received_at) AS first_seen,
       MAX(received_at) AS last_seen,
       COUNT(*)         AS row_count
FROM request_telemetry
WHERE app_id = $1
  AND received_at > now() - $2::interval
GROUP BY deployment_id
ORDER BY last_seen DESC
LIMIT $3
`

type ListDeploymentsForCompareParams struct {
	AppID   pgtype.UUID
	Column2 pgtype.Interval
	Limit   int32
}

type ListDeploymentsForCompareRow struct {
	DeploymentID pgtype.UUID
	FirstSeen    interface{}
	LastSeen     interface{}
	RowCount     int64
}

// Backs the dashboard compare panel's two `<select>` dropdowns: "pick
// source deployment" and "pick mirror deployment". GROUP BY on
// request_telemetry reads the distinct deployment_ids that have
// shipped traffic in the window. first_seen/last_seen row_count give
// the dashboard enough metadata to render "v81 — 17m of traffic,
// 4123 rows" without a second query.
//
// PR-B uses this to seed the dropdowns; the actual percentile
// comparison is two RequestTelemetryBaselineP95ByRoute calls in Go
// (PR-A ships that query; the regression cron uses the same shape).
func (q *Queries) ListDeploymentsForCompare(ctx context.Context, db DBTX, arg ListDeploymentsForCompareParams) ([]ListDeploymentsForCompareRow, error) {
	rows, err := db.Query(ctx, listDeploymentsForCompare, arg.AppID, arg.Column2, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListDeploymentsForCompareRow{}
	for rows.Next() {
		var i ListDeploymentsForCompareRow
		if err := rows.Scan(
			&i.DeploymentID,
			&i.FirstSeen,
			&i.LastSeen,
			&i.RowCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

